if (!game.canvasMotion) return ui.notifications.error("Canvas Motion não está ativo.");
const state = game.canvasMotion.status();
console.info("[Canvas Motion] Estado atual:", state);
ui.notifications.info(`Canvas Motion: ${state.active ? (state.paused ? "pausado" : "em movimento") : "parado"}${state.direction ? ` — ${state.direction}, ${state.speed} px/s` : ""}`);
